// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, address caller) public {
        // keep caller as a wide fuzzed address but non-zero to be reasonable
        if(caller == address(0)) caller = address(1);

        // For the correct contract, before initialization we expect SetMinSum to succeed and set MinSum to _val.
        // The mutant removed the guard and thus may allow changes at times the original would block.
        bool ok;
        vm.prank(caller);
        try c.SetMinSum(_val) { ok = true; } catch { ok = false; }

        // The universal property: after calling SetMinSum(_val) the public getter MinSum() equals _val
        // (and the call did not revert). This holds for the reference contract for all inputs.
        // The mutant that removed the revert guard will cause divergence for some inputs (fuzzer will find one).
        assertTrue(ok && c.MinSum() == _val);
    }
}

