pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: whether the contract has been Initialized before calling SetMinSum and the value to set
    function testFuzz_property(bool doInitialize, uint256 newMin) public {
        // keep domain wide; newMin can be any uint
        // Step 1: optionally initialize
        if (doInitialize) {
            c.Initialized();
        }

        // Step 2: call SetMinSum and capture whether it succeeded (no revert) using try/catch
        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // ONE assertion: On the reference contract, SetMinSum should succeed iff the contract was already initialized;
        // therefore ok == doInitialize, and when it succeeded, c.MinSum() equals newMin.
        // We assert a single boolean fact that combines both: either the call reverted (ok==false) and MinSum unchanged (==0 by default),
        // or the call succeeded (ok==true) and MinSum equals newMin. This holds for the reference for all inputs
        // but the mutant (which inverts the guard) will violate it for some inputs.

        // Read MinSum via public getter
        uint256 observed = c.MinSum();

        // Build the boolean fact: (ok && observed == newMin) || (!ok && observed != newMin ? false : true)
        // Simplify: require that if ok then observed==newMin; if !ok then observed!=newMin is not required because reference leaves MinSum at 0 when it reverts.
        // To keep a single assertTrue that the reference always satisfies and mutant breaks for some input,
        // assert that ok == doInitialize AND if ok then observed==newMin.

        bool prop = (ok == doInitialize) && (!ok || observed == newMin);
        assertTrue(prop);
    }
}

