pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed _val and a boolean initFlag to control whether Initialized() is called
    function testFuzz_property(bool initFlag, uint256 _val) public {
        // keep _val wide but avoid extremely large values not needed — no tight constraints
        // We need to exercise the case where the contract is initialized: that is part of admissible domain
        if (initFlag) {
            // mark contract initialized
            c.Initialized();
        }

        // Call SetMinSum and observe whether it reverts. For the reference C, SetMinSum should
        // succeed when initFlag==true (contract initialized) and set MinSum to _val.
        // The mutant inverts the guard and will revert when initFlag==true, so this distinguishes them.

        bool ok;
        try c.SetMinSum(_val) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees: if we called Initialized() (initFlag==true), then
        // SetMinSum should succeed and MinSum() equals the provided _val.
        // We assert that property: when initFlag is true, the call succeeded and MinSum==_val.
        // This holds for the reference implementation for all inputs; the mutant will fail for some.
        if (initFlag) {
            assertTrue(ok && c.MinSum() == _val);
        } else {
            // if not initialized, the reference may revert (disallow setting) — we do not constrain this
            // so simply assert true to avoid making additional guarantees.
            assertTrue(true);
        }
    }
}

