contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter is the deciding value to set MinSum to
    function testFuzz_property(uint256 newMin) public {
        // admissible domain: any uint256 is allowed; no further restriction needed
        // 1) initialize the contract so SetMinSum is allowed in the reference
        c.Initialized();

        // 2) call SetMinSum with the fuzzed value and record whether it succeeded
        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: in the REFERENCE, when Initialized() was called, SetMinSum
        // must succeed and MinSum() equals the provided value for ALL inputs. The mutant
        // (inverted guard) will cause the call to revert (ok==false) for some inputs.
        // Thus we assert that if the call succeeded, then c.MinSum() equals newMin.
        // This property holds for the reference for every newMin, and the mutant breaks it
